import{_ as a,o,c as n,a2 as t}from"./chunks/framework.1C62pOns.js";const r="/pro-agent-hub-installer/capturas/es/whatsapp-detalhe.png",s="/pro-agent-hub-installer/capturas/es/msteams-detalhe.png",h=JSON.parse('{"title":"Integraciones","description":"","frontmatter":{},"headers":[],"relativePath":"es/interface/integracoes.md","filePath":"es/interface/integracoes.md","lastUpdated":1787856241000}'),i={name:"es/interface/integracoes.md"};function l(p,e,c,d,u,m){return o(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="integraciones" tabindex="-1">Integraciones <a class="header-anchor" href="#integraciones" aria-label="Permalink to &quot;Integraciones&quot;">​</a></h1><p>Llevan un agente o un equipo a donde la gente ya conversa, en vez de pedirles que entren en la plataforma.</p><p>Las dos integraciones funcionan igual: la plataforma expone un <strong>webhook</strong>, el servicio externo llama a esa dirección en cada mensaje recibido, el agente responde y la plataforma devuelve la respuesta por el mismo canal.</p><p>En ambas vinculas <strong>un agente o un equipo</strong> — nunca los dos.</p><h2 id="whatsapp" tabindex="-1">WhatsApp <a class="header-anchor" href="#whatsapp" aria-label="Permalink to &quot;WhatsApp&quot;">​</a></h2><p><img src="'+r+'" alt="whatsapp-detalhe"></p><p>La conexión es vía <strong>Evolution API</strong>, que es quien habla con WhatsApp de verdad. El registro guarda la dirección del servidor, la clave de la API y el nombre de la instancia.</p><p>Tras guardar, copia la <strong>dirección del webhook</strong> de la pantalla y configúrala en la Evolution API. Sin ese paso, la integración queda registrada y nunca recibe nada — es el error más común.</p><p><strong>El token del webhook es obligatorio.</strong> Es lo que distingue un mensaje venido de tu Evolution API de cualquier petición que dé con la dirección. Sin token comprobado, el webhook sería una puerta abierta.</p><h3 id="dos-opciones-que-cambian-el-comportamiento" tabindex="-1">Dos opciones que cambian el comportamiento <a class="header-anchor" href="#dos-opciones-que-cambian-el-comportamiento" aria-label="Permalink to &quot;Dos opciones que cambian el comportamiento&quot;">​</a></h3><p><strong>Modo público.</strong> Activado, todos los mensajes se tratan como el usuario de servicio de la plataforma, en vez de crear un usuario por número de teléfono. Es lo que quieres en una atención abierta al público; es lo que <strong>no</strong> quieres cuando cada persona debe tener su propio historial.</p><p><strong>Responder errores.</strong> Activado, un fallo de procesamiento se convierte en un mensaje para quien escribió. Puedes sustituir el texto crudo de la excepción por uno tuyo — y deberías: un mensaje de error técnico en el WhatsApp de un cliente no ayuda a nadie.</p><h2 id="microsoft-teams" tabindex="-1">Microsoft Teams <a class="header-anchor" href="#microsoft-teams" aria-label="Permalink to &quot;Microsoft Teams&quot;">​</a></h2><p><img src="'+s+'" alt="msteams-detalhe"></p><p>La conexión es por un <strong>bot registrado en Azure</strong>. El registro guarda el App ID, la contraseña del bot y, opcionalmente, el tenant.</p><p>El camino es el inverso al de WhatsApp: primero registra el bot en Azure, después apunta su <em>messaging endpoint</em> al webhook que esta pantalla muestra.</p><p>Conviene saberlo antes de empezar: el registro del bot se hace en el portal de Azure, fuera de la plataforma, y suele depender de quien administra el tenant de la empresa. Es la parte lenta.</p>',17)])])}const b=a(i,[["render",l]]);export{h as __pageData,b as default};
